const source = ($json.body && typeof $json.body === 'object') ? $json.body : $json;

const text = (value, max = 500) => String(value ?? '').normalize('NFC').trim().slice(0, max);
const required = (value, name, max = 100) => {
  const result = text(value, max);
  if (!result) throw new Error(`${name} is required`);
  return result;
};
const array = (value, name, max) => {
  if (value === undefined || value === null) return [];
  if (!Array.isArray(value)) throw new Error(`${name} must be an array`);
  if (value.length > max) throw new Error(`${name} exceeds ${max} rows`);
  return value;
};
const unique = (rows, keyOf) => [...new Map(rows.map(row => [keyOf(row), row])).values()];

const companyId = required(source.company_id, 'company_id', 64);
const divisionKey = required(source.division_key, 'division_key', 64);
const version = text(source.version, 100) || new Date().toISOString();

const articles = unique(
  array(source.articles, 'articles', 100000).map((row, index) => {
    const articleCode = required(row?.article_code, `articles[${index}].article_code`, 200);
    return {
      article_code: articleCode,
      article_name: text(row?.article_name, 500),
      buyer_reference: text(row?.buyer_reference, 500),
    };
  }),
  row => `${row.article_code.toLocaleLowerCase('en')}\u001f${row.buyer_reference.toLocaleLowerCase('en')}`,
);

const styleOptions = unique(
  array(source.style_options, 'style_options', 20000).map((row, index) => {
    const fieldName = required(row?.field_name, `style_options[${index}].field_name`, 100)
      .toLocaleLowerCase('en')
      .replace(/[ -]+/g, '_');
    const optionValue = required(row?.option_value, `style_options[${index}].option_value`, 500);
    return {
      material_type: text(row?.material_type, 100).toLocaleUpperCase('en'),
      field_name: fieldName,
      option_value: optionValue,
      option_label: text(row?.option_label, 500) || optionValue,
    };
  }),
  row => `${row.material_type}\u001f${row.field_name}\u001f${row.option_value.toLocaleLowerCase('en')}`,
);

const styleSubcategories = unique(
  array(source.style_subcategories, 'style_subcategories', 20000).map((row, index) => ({
    material_type: text(row?.material_type, 100).toLocaleUpperCase('en'),
    product_group: required(row?.product_group, `style_subcategories[${index}].product_group`, 500),
    sub_category: required(row?.sub_category, `style_subcategories[${index}].sub_category`, 500),
  })),
  row => `${row.material_type}\u001f${row.product_group.toLocaleLowerCase('en')}\u001f${row.sub_category.toLocaleLowerCase('en')}`,
);

return [{ json: {
  company_id: companyId,
  division_key: divisionKey,
  version,
  articles_json: JSON.stringify(articles),
  style_options_json: JSON.stringify(styleOptions),
  style_subcategories_json: JSON.stringify(styleSubcategories),
} }];

const query = ($json.query && typeof $json.query === 'object') ? $json.query : {};
const text = (value, max = 100) => String(value ?? '').normalize('NFC').trim().slice(0, max);
const companyId = text(query.company_id, 64);
const divisionKey = text(query.division_key, 64);
if (!companyId) throw new Error('company_id is required');
if (!divisionKey) throw new Error('division_key is required');
return [{ json: {
  company_id: companyId,
  division_key: divisionKey,
  client_version: text(query.client_version, 100),
} }];
